<?php
require __DIR__ . '/config.php';
require_role('admin');
$studentId=max(0,(int)($_GET['id']??0));
$sql='SELECT s.id,s.student_no,s.class_level,s.active,s.created_at AS student_created_at,u.full_name,u.username FROM students s JOIN users u ON u.id=s.user_id';
if($studentId){$st=$pdo->prepare($sql.' WHERE s.id=?');$st->execute([$studentId]);$students=$st->fetchAll(PDO::FETCH_ASSOC);}
else{$students=$pdo->query($sql.' ORDER BY u.full_name ASC')->fetchAll(PDO::FETCH_ASSOC);}
if($studentId&&!$students){http_response_code(404);exit('Data santri tidak ditemukan.');}
$school=app_school_name();$logo=app_school_logo_url();
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Data Santri - <?=h($school)?></title><style>
:root{--navy:#142b4a;--line:#d7dee8;--muted:#64748b}*{box-sizing:border-box}body{font:12px/1.45 Arial,Helvetica,sans-serif;color:#172334;margin:0;background:#eef2f7}.toolbar{display:flex;gap:10px;justify-content:center;padding:18px}.btn{border:0;border-radius:6px;padding:10px 17px;font-weight:700;cursor:pointer;text-decoration:none;font-size:13px}.print{background:var(--navy);color:#fff}.back{background:#fff;color:var(--navy);border:1px solid var(--line)}.paper{background:#fff;max-width:1200px;margin:0 auto 24px;padding:24px 28px;box-shadow:0 4px 24px #17233412}.head{display:flex;align-items:center;gap:15px;border-bottom:3px solid var(--navy);padding-bottom:14px}.logo{width:64px;height:64px;object-fit:contain}.identity h1{font-size:18px;margin:0 0 4px;color:var(--navy);letter-spacing:.4px}.identity p{margin:0;color:var(--muted)}.title{text-align:center;margin:18px 0}.title h2{margin:0;color:var(--navy);font-size:16px;letter-spacing:.6px}.title p{margin:5px 0 0;color:var(--muted)}.meta{display:flex;justify-content:space-between;padding:9px 11px;background:#f5f7fa;border:1px solid var(--line);margin-bottom:12px}.summary{font-weight:bold;color:var(--navy);margin:10px 0}table{width:100%;border-collapse:collapse}thead{display:table-header-group}tr{break-inside:avoid}th{background:var(--navy);color:#fff;text-align:left}th,td{border:1px solid var(--line);padding:8px 7px}tbody tr:nth-child(even){background:#f8fafc}.center{text-align:center}.footer{display:flex;justify-content:space-between;border-top:1px solid var(--line);margin-top:18px;padding-top:8px;color:var(--muted);font-size:10px}@page{size:A4 landscape;margin:12mm;@bottom-right{content:"Halaman " counter(page) " dari " counter(pages);font:9px Arial;color:#64748b}}@media print{body{background:#fff;font-size:9px}.toolbar{display:none}.paper{max-width:none;margin:0;padding:0;box-shadow:none}.logo{width:48px;height:48px}.identity h1{font-size:15px}.title{margin:12px 0}.title h2{font-size:14px}th,td{padding:6px 5px;font-size:8.5px}.meta{padding:6px 8px}.footer{margin-top:10px}} </style></head><body><div class="toolbar"><button class="btn print" onclick="window.print()">Cetak PDF</button><button class="btn back" onclick="history.length>1?history.back():location.href='students.php'">Kembali</button></div><main class="paper"><header class="head"><?php if($logo):?><img class="logo" src="<?=h($logo)?>" alt="Logo pesantren"><?php endif;?><div class="identity"><h1><?=h(mb_strtoupper($school,'UTF-8'))?></h1><p>Dokumen Administrasi Pesantren · Sistem Santri Go</p></div></header><div class="title"><h2><?= $studentId?'KARTU DATA SANTRI':'DAFTAR DATA SANTRI' ?></h2><p>Data administrasi santri</p></div><div class="meta"><span><b>Tanggal cetak:</b> <?=date('d/m/Y H:i')?></span><span><b>Jenis dokumen:</b> <?=$studentId?'Data individu':'Daftar santri'?></span></div><div class="summary">Total data: <?=number_format(count($students),0,',','.')?> santri</div><table><thead><tr><th class="center">No.</th><th>Nomor induk</th><th>Nama lengkap</th><th>Jenjang</th><th>Username</th><th>Status</th><th>Tanggal terdaftar</th></tr></thead><tbody><?php if(!$students):?><tr><td colspan="7" class="center">Belum ada data santri.</td></tr><?php else:foreach($students as $i=>$s):?><tr><td class="center"><?=$i+1?></td><td><?=h($s['student_no'])?></td><td><?=h($s['full_name'])?></td><td><?=h($s['class_level'])?></td><td><?=h($s['username'])?></td><td><?=!empty($s['active'])?'Aktif':'Nonaktif'?></td><td><?=h(date('d/m/Y',strtotime($s['student_created_at'])))?></td></tr><?php endforeach;endif;?></tbody></table><footer class="footer"><span><?=h($school)?> · Dokumen administrasi santri</span><span>Dicetak melalui Santri Go</span></footer></main><script>window.addEventListener('load',()=>setTimeout(()=>window.print(),350));</script></body></html>